CREATE TABLE public.profiles (id uuid PRIMARY KEY, name text NOT NULL DEFAULT '', age int, bio text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.chats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chat_id uuid NOT NULL REFERENCES public.chats(id) ON DELETE CASCADE, sender_id uuid NOT NULL, sender_name text NOT NULL DEFAULT '', content text NOT NULL DEFAULT '', image_url text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT content_len CHECK (char_length(content) <= 200000));
CREATE INDEX ON public.messages(chat_id, created_at);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles, public.chats, public.messages TO anon, authenticated;
GRANT ALL ON public.profiles, public.chats, public.messages TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chats ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "open" ON public.profiles FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "open" ON public.chats FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "open" ON public.messages FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages;
ALTER PUBLICATION supabase_realtime ADD TABLE public.chats;
CREATE POLICY "chat images read" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'chat-images');
CREATE POLICY "chat images upload" ON storage.objects FOR INSERT TO anon, authenticated WITH CHECK (bucket_id = 'chat-images');